{
  "templateId": "travel",
  "templateVersion": 4,
  "title": "Travel",
  "description_template": "{traveller_name} – flight from {from_location} to {to_location} on {depart_date}[[ for {purpose}]].",
  "sections": [
    {
      "id": "detail",
      "type": "fields",
      "title": "Trip",
      "layout": "grid",
      "columns": 2,
      "fields": [
        {
          "key": "traveller_name",
          "label": "Traveller Name",
          "type": "text",
          "required": true,
          "bind": "user.full_name"
        },
        {
          "key": "purpose",
          "label": "Purpose",
          "type": "text",
          "required": true
        },
        {
          "key": "from_location",
          "label": "From",
          "type": "text",
          "required": true
        },
        {
          "key": "to_location",
          "label": "To",
          "type": "text",
          "required": true
        },
        {
          "key": "depart_date",
          "label": "Departure Date",
          "type": "date",
          "required": true
        }
      ]
    },
    {
      "id": "proof",
      "type": "image_attachments",
      "title": "Proof",
      "columns": 2,
      "slots": [
        {
          "key": "bill",
          "label": "Ticket / Invoice",
          "accept": "image/*,application/pdf",
          "maxSizeMb": 5,
          "maps_to": "invoice_attachment"
        }
      ]
    }
  ]
}

