{
  "templateId": "labour-accommodation",
  "templateVersion": 3,
  "title": "Labour Accommodation",
  "sections": [
    {
      "id": "detail",
      "type": "fields",
      "title": "Labour Accommodation",
      "layout": "grid",
      "columns": 2,
      "fields": [
        {
          "key": "accommodation_type",
          "label": "Accommodation Type",
          "type": "select",
          "options": [
            "PG",
            "Hotel",
            "Flat / House",
            "Guest House",
            "Other"
          ],
          "required": true
        },
        {
          "key": "building_name",
          "label": "Building Name",
          "type": "text",
          "required": true
        },
        {
          "key": "city",
          "label": "City",
          "type": "text"
        },
        {
          "key": "rent_period_from",
          "label": "Rent Period From",
          "type": "date",
          "required": true
        },
        {
          "key": "rent_period_to",
          "label": "Rent Period To",
          "type": "date",
          "required": true
        },
        {
          "key": "no_of_occupants",
          "label": "No. of Occupants",
          "type": "number",
          "min": 1,
          "required": true
        },
        {
          "key": "rent_per_occupant",
          "label": "Rent per Occupant",
          "type": "number",
          "min": 0
        }
      ]
    },
    {
      "id": "proof",
      "type": "image_attachments",
      "title": "Proof",
      "columns": 2,
      "slots": [
        {
          "key": "bill",
          "label": "Bill / Receipt",
          "accept": "image/*,application/pdf",
          "maxSizeMb": 5,
          "maps_to": "invoice_attachment"
        }
      ]
    }
  ]
}

